// ==== perfil.js ====
/* static/js/modules/pasta_painel/modulos/perfil/perfil.js
============================================
PERFIL — usa Mockup global
============================================ */

(function() {
    'use strict';

    document.addEventListener('DOMContentLoaded', function() {
        const form = document.getElementById('formPerfil');
        if (!form) return;

        const inputUsername = document.getElementById('username');
        const feedbackUsername = document.getElementById('usernameFeedback');
        const inputBio = document.getElementById('bio');
        const bioContador = document.getElementById('bioContador');
        const inputNomeExibicao = document.getElementById('nome_exibicao');
        const inputFoto = document.getElementById('foto');
        const inputRemoverFoto = document.getElementById('remover_foto');
        const fotoPreview = document.getElementById('fotoPreview');
        const btnRemoverFoto = document.getElementById('btnRemoverFoto');
        const btnSalvar = document.getElementById('btnSalvarPerfil');
        const inputFotoPosicao = document.getElementById('foto_posicao');

        function atualizarMockup() {
            if (!window.Mockup) return;
            if (inputNomeExibicao) Mockup.setNome(inputNomeExibicao.value.trim());
            if (inputBio) Mockup.setBio(inputBio.value.trim());
        }

        // USERNAME (validação)
        let timeoutUsername = null;
        if (inputUsername) {
            inputUsername.addEventListener('input', function() {
                const username = this.value.trim().toLowerCase();
                this.value = username;
                clearTimeout(timeoutUsername);

                if (!username) {
                    feedbackUsername.textContent = 'Letras minúsculas, números e _.';
                    feedbackUsername.className = 'form-hint';
                    return;
                }
                if (username.length < 3) {
                    feedbackUsername.textContent = 'Mínimo 3 caracteres.';
                    feedbackUsername.className = 'form-hint form-hint-erro';
                    return;
                }
                if (!/^[a-z][a-z0-9_]*$/.test(username)) {
                    feedbackUsername.textContent = 'Só minúsculas, números e _ (começar com letra).';
                    feedbackUsername.className = 'form-hint form-hint-erro';
                    return;
                }

                feedbackUsername.textContent = 'Verificando...';
                feedbackUsername.className = 'form-hint form-hint-verificando';

                timeoutUsername = setTimeout(() => {
                    fetch('/painel/perfil/verificar-username/' + encodeURIComponent(username))
                        .then(r => r.json())
                        .then(data => {
                            if (data.disponivel) {
                                feedbackUsername.textContent = '✅ Disponível!';
                                feedbackUsername.className = 'form-hint form-hint-ok';
                            } else {
                                feedbackUsername.textContent = '❌ ' + (data.message || 'Indisponível.');
                                feedbackUsername.className = 'form-hint form-hint-erro';
                            }
                        })
                        .catch(() => {
                            feedbackUsername.textContent = 'Erro ao verificar.';
                            feedbackUsername.className = 'form-hint form-hint-erro';
                        });
                }, 500);
            });
        }

        // NOME
        if (inputNomeExibicao) {
            inputNomeExibicao.addEventListener('input', atualizarMockup);
        }

        // BIO
        if (inputBio && bioContador) {
            const atualizar = () => {
                bioContador.textContent = inputBio.value.length;
                atualizarMockup();
            };
            inputBio.addEventListener('input', atualizar);
            atualizar();
        }

        // POSIÇÃO DO CORTE
        if (inputFotoPosicao) {
            inputFotoPosicao.addEventListener('change', function() {
                const preview = document.getElementById('fotoPreview');
                if (preview) {
                    const img = preview.querySelector('img');
                    if (img) {
                        img.style.objectPosition = 'center ' + this.value;
                    }
                }
                if (window.Mockup && Mockup.setFotoPosicao) {
                    Mockup.setFotoPosicao(this.value);
                }
            });
        }

        // FOTO — upload
        if (inputFoto) {
            inputFoto.addEventListener('change', function() {
                const file = this.files[0];
                if (!file) return;

                if (file.size > 2 * 1024 * 1024) {
                    if (window.Notificacao) Notificacao.erro('Imagem muito grande. Máximo 2MB.');
                    this.value = '';
                    return;
                }

                const reader = new FileReader();
                reader.onload = (e) => {
                    const src = e.target.result;

                    // ⚠️ FIX: pega a posição ATUAL do select e aplica
                    const posicao = inputFotoPosicao ? inputFotoPosicao.value : 'top';

                    if (fotoPreview) {
                        fotoPreview.innerHTML = `<img src="${src}" alt="Preview" style="object-position: center ${posicao};">`;
                    }
                    if (window.Mockup) {
                        // Seta a foto (Mockup.setFoto já pega a posição do select)
                        Mockup.setFoto(src);
                    }
                };
                reader.readAsDataURL(file);

                if (inputRemoverFoto) inputRemoverFoto.value = '0';
                if (btnRemoverFoto) btnRemoverFoto.disabled = false;
            });
        }

        // FOTO — remover
        if (btnRemoverFoto) {
            btnRemoverFoto.addEventListener('click', function() {
                if (inputRemoverFoto) inputRemoverFoto.value = '1';
                if (inputFoto) inputFoto.value = '';

                const placeholder = '<div class="pp-foto-placeholder"><i class="fas fa-user"></i></div>';
                if (fotoPreview) fotoPreview.innerHTML = placeholder;

                if (window.Mockup) Mockup.setFoto(null);

                btnRemoverFoto.disabled = true;

                if (window.Notificacao) {
                    Notificacao.aviso('Foto marcada pra remoção. Salva pra confirmar.');
                }
            });
        }

        // SUBMIT
        form.addEventListener('submit', function(ev) {
            ev.preventDefault();

            const formData = new FormData(form);

            if (btnSalvar) {
                btnSalvar.disabled = true;
                const texto = btnSalvar.querySelector('.btn-texto');
                const loading = btnSalvar.querySelector('.btn-loading');
                if (texto) texto.hidden = true;
                if (loading) loading.hidden = false;
            }

            fetch('/painel/perfil/salvar', {
                method: 'POST',
                body: formData,
                headers: { 'X-Requested-With': 'XMLHttpRequest' }
            })
            .then(r => r.json().then(j => ({ ok: r.ok, data: j })))
            .then(({ ok, data }) => {
                if (!ok || !data.success) {
                    const msg = data.error || 'Erro ao salvar.';
                    if (window.Notificacao) Notificacao.erro(msg);
                    return;
                }
                if (window.Notificacao) Notificacao.sucesso(data.message || 'Perfil atualizado!');

                if (inputRemoverFoto) inputRemoverFoto.value = '0';
                if (btnRemoverFoto) btnRemoverFoto.disabled = true;
            })
            .catch(() => {
                if (window.Notificacao) Notificacao.erro('Erro de conexão.');
            })
            .finally(() => {
                if (btnSalvar) {
                    btnSalvar.disabled = false;
                    const texto = btnSalvar.querySelector('.btn-texto');
                    const loading = btnSalvar.querySelector('.btn-loading');
                    if (texto) texto.hidden = false;
                    if (loading) loading.hidden = true;
                }
            });
        });

        atualizarMockup();
        console.log('✅ Perfil carregado');
    });
})();

// ==== aparencia.js ====
/* static/js/modules/pasta_painel/modulos/aparencia/aparencia.js */

(function() {
    'use strict';

    document.addEventListener('DOMContentLoaded', function() {
        const form = document.getElementById('formAparencia');
        if (!form) return;

        const inputCorPrimaria = document.getElementById('cor_primaria');
        const inputCorSecundaria = document.getElementById('cor_secundaria');
        const inputCorFundo = document.getElementById('cor_fundo');
        const inputCorTexto = document.getElementById('cor_texto');
        const inputFonte = document.getElementById('fonte');
        const inputEstiloBotao = document.getElementById('estilo_botao');
        const inputTamanhoFoto = document.getElementById('tamanho_foto');
        const inputTamanhoLink = document.getElementById('tamanho_link');
        const inputEspacamento = document.getElementById('espacamento_links');
        const inputBordaLink = document.getElementById('borda_link');
        const inputHoverEfeito = document.getElementById('hover_efeito');
        const inputAnimacaoEntrada = document.getElementById('animacao_entrada');

        const btnSalvarFooter = document.getElementById('btnSalvarFooter');

        const hexPrimaria = document.getElementById('corPrimariaHex');
        const hexSecundaria = document.getElementById('corSecundariaHex');
        const hexFundo = document.getElementById('corFundoHex');
        const hexTexto = document.getElementById('corTextoHex');

        function atualizarMockup() {
            if (!window.Mockup) return;

            // Cores
            Mockup.setCores(
                inputCorPrimaria?.value,
                inputCorSecundaria?.value,
                inputCorFundo?.value,
                inputCorTexto?.value
            );

            // Estilo, fonte, tamanhos
            if (inputEstiloBotao) Mockup.setEstiloBotao(inputEstiloBotao.value);
            if (inputFonte) Mockup.setFonte(inputFonte.value);
            if (Mockup.setTamanhos) {
                Mockup.setTamanhos(
                    inputTamanhoFoto?.value,
                    inputTamanhoLink?.value,
                    inputEspacamento?.value
                );
            }

            // NOVO: borda, hover, animação
            if (inputBordaLink && Mockup.setBorda) Mockup.setBorda(inputBordaLink.value);
            if (inputHoverEfeito && Mockup.setHover) Mockup.setHover(inputHoverEfeito.value);
            if (inputAnimacaoEntrada && Mockup.setAnimacao) Mockup.setAnimacao(inputAnimacaoEntrada.value);
        }

        // Listeners de cor
        if (inputCorPrimaria) inputCorPrimaria.addEventListener('input', function() {
            if (hexPrimaria) hexPrimaria.textContent = this.value;
            atualizarMockup();
        });
        if (inputCorSecundaria) inputCorSecundaria.addEventListener('input', function() {
            if (hexSecundaria) hexSecundaria.textContent = this.value;
            atualizarMockup();
        });
        if (inputCorFundo) inputCorFundo.addEventListener('input', function() {
            if (hexFundo) hexFundo.textContent = this.value;
            atualizarMockup();
        });
        if (inputCorTexto) inputCorTexto.addEventListener('input', function() {
            if (hexTexto) hexTexto.textContent = this.value;
            atualizarMockup();
        });

        // Listeners de estilo + tamanhos + borda + hover + animação
        [
            inputFonte, inputEstiloBotao,
            inputTamanhoFoto, inputTamanhoLink, inputEspacamento,
            inputBordaLink, inputHoverEfeito, inputAnimacaoEntrada
        ].forEach(el => {
            if (el) el.addEventListener('change', atualizarMockup);
        });

        // Templates
        document.querySelectorAll('.template-card').forEach(card => {
            card.addEventListener('click', function() {
                document.querySelectorAll('.template-card').forEach(c => c.classList.remove('active'));
                this.classList.add('active');

                const template = this.dataset.template;
                const primaria = this.dataset.primaria;
                const secundaria = this.dataset.secundaria;
                const fundo = this.dataset.fundo;
                const texto = this.dataset.texto;

                const templateHidden = document.getElementById('template_hidden');
                if (templateHidden) templateHidden.value = template;

                if (inputCorPrimaria && primaria) { inputCorPrimaria.value = primaria; if (hexPrimaria) hexPrimaria.textContent = primaria; }
                if (inputCorSecundaria && secundaria) { inputCorSecundaria.value = secundaria; if (hexSecundaria) hexSecundaria.textContent = secundaria; }
                if (inputCorFundo && fundo) { inputCorFundo.value = fundo; if (hexFundo) hexFundo.textContent = fundo; }
                if (inputCorTexto && texto) { inputCorTexto.value = texto; if (hexTexto) hexTexto.textContent = texto; }

                atualizarMockup();
            });
        });

        // Submit
        function submeter() {
            const formData = new FormData(form);

            if (btnSalvarFooter) {
                btnSalvarFooter.disabled = true;
                const icone = btnSalvarFooter.querySelector('i');
                if (icone) icone.className = 'fas fa-spinner fa-spin';
            }

            fetch('/painel/aparencia/salvar', {
                method: 'POST',
                body: formData,
                headers: { 'X-Requested-With': 'XMLHttpRequest' }
            })
            .then(r => r.json().then(j => ({ ok: r.ok, data: j })))
            .then(({ ok, data }) => {
                if (!ok || !data.success) {
                    if (window.Notificacao) Notificacao.erro(data.error || 'Erro ao salvar.');
                    return;
                }
                if (window.Notificacao) Notificacao.sucesso(data.message || 'Aparência atualizada!');
            })
            .catch(() => {
                if (window.Notificacao) Notificacao.erro('Erro de conexão.');
            })
            .finally(() => {
                if (btnSalvarFooter) {
                    btnSalvarFooter.disabled = false;
                    const icone = btnSalvarFooter.querySelector('i');
                    if (icone) icone.className = 'fas fa-save';
                }
            });
        }

        form.addEventListener('submit', function(ev) {
            ev.preventDefault();
            submeter();
        });

        if (btnSalvarFooter) {
            btnSalvarFooter.addEventListener('click', function() {
                submeter();
            });
        }

        atualizarMockup();
        console.log('✅ Aparência carregada');
    });
})();

// ==== config.js ====
/* static/js/modules/pasta_painel/modulos/config/config.js
============================================
CONFIGURAÇÕES — alterar senha
============================================ */

(function() {
    'use strict';

    const form = document.getElementById('formAlterarSenha');
    if (!form) return;

    const btnAlterar = document.getElementById('btnAlterarSenha');
    const btnDeletar = document.getElementById('btnDeletarConta');

    // ==========================================================
    // ALTERAR SENHA
    // ==========================================================
    form.addEventListener('submit', function(ev) {
        ev.preventDefault();
        const formData = new FormData(form);

        if (btnAlterar) {
            btnAlterar.classList.add('loading');
            btnAlterar.disabled = true;
        }

        fetch('/painel/configuracoes/alterar-senha', {
            method: 'POST',
            body: formData,
            headers: { 'X-Requested-With': 'XMLHttpRequest' }
        })
        .then(r => r.json().then(j => ({ ok: r.ok, data: j })))
        .then(({ ok, data }) => {
            if (!ok || !data.success) {
                Notificacao.erro(data.error || 'Erro ao alterar senha.');
                return;
            }
            Notificacao.sucesso(data.message || 'Senha alterada!');
            form.reset();
        })
        .catch(() => Notificacao.erro('Erro de conexão.'))
        .finally(() => {
            if (btnAlterar) {
                btnAlterar.classList.remove('loading');
                btnAlterar.disabled = false;
            }
        });
    });

    // ==========================================================
    // DELETAR CONTA (placeholder — futuro)
    // ==========================================================
    if (btnDeletar) {
        btnDeletar.addEventListener('click', function() {
            Notificacao.aviso('Função em desenvolvimento. Fale com o suporte.');
        });
    }

    console.log('✅ Config carregado');

})();

